    private int SubmittedApplicationId { get; set; }
    private string ErrorMessage { get; set; } = string.Empty;

    // Step 1 fields
    private string FullName { get; set; } = string.Empty;
    private string Email { get; set; } = string.Empty;
    private string Phone { get; set; } = string.Empty;
    private string Address { get; set; } = string.Empty;

    // Step 2 fields
    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };

    // Step 3 fields
    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 fields
    private string CoverLetter { get; set; } = string.Empty;

    private string GetStepClass(int stepIndex)
    {
        if (stepIndex == CurrentStep) return "active";
        if (stepIndex <= HighestCompletedStep) return "completed";
        return "future";
    }

    private void GoToStep(int step)
    {
        if (step <= HighestCompletedStep || step == CurrentStep)
        {
            ErrorMessage = string.Empty;
            CurrentStep = step;
        }
    }

    private void NextStep()
    {
        ErrorMessage = string.Empty;
        if (CurrentStep > HighestCompletedStep)
            HighestCompletedStep = CurrentStep;
        CurrentStep++;
    }

    private void PreviousStep()
    {
        ErrorMessage = string.Empty;
        CurrentStep--;
    }

    private async Task NextFromPersonalInfo()
    {
        ErrorMessage = string.Empty;

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            ErrorMessage = "Please fill in all required fields.";
            return;
        }

        IsLoading = true;
        try
        {
            var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
            if (!isValidEmail)
            {
                ErrorMessage = "The email address is not valid. Please enter a valid email.";
                return;
            }
            NextStep();
        }
        finally
        {
            IsLoading = false;
        }
    }

    private void NextFromWorkHistory()
    {
        ErrorMessage = string.Empty;
        foreach (var entry in WorkEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
            {
                ErrorMessage = "Please fill in company, job title, and start date for all positions.";
                return;
            }
        }
        NextStep();
    }

    private void NextFromReferences()
    {
        ErrorMessage = string.Empty;
        foreach (var reference in References)
        {
            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
            {
                ErrorMessage = "Please fill in all required fields for each reference.";
                return;
            }
        }
        NextStep();
    }

    private async Task SubmitApplication()
    {
        IsLoading = true;
        ErrorMessage = string.Empty;
        try
        {
            var personal = new PersonalInfo(FullName, Email, Phone, Address);
            var workHistory = new WorkHistory(WorkEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var application = new JobApplication(personal, workHistory, references, CoverLetter);

            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
            IsSubmitted = true;
        }
        catch (Exception ex)
        {
            ErrorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            IsLoading = false;
        }
    }

    // Work entry helpers
    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
    private void RemoveWorkEntry(int index) => WorkEntries.RemoveAt(index);

    private void UpdateWorkEntry(int index, string field, string? value)
    {
        var entry = WorkEntries[index];
        switch (field)
        {
            case nameof(WorkEntryModel.Company): entry.Company = value ?? string.Empty; break;
            case nameof(WorkEntryModel.Title): entry.Title = value ?? string.Empty; break;
            case nameof(WorkEntryModel.Description): entry.Description = value ?? string.Empty; break;
        }
    }

    private void UpdateWorkEntryDate(int index, bool isStart, string? value)
    {
        if (DateTime.TryParse(value, out var date))
        {
            if (isStart) WorkEntries[index].StartDate = date;
            else WorkEntries[index].EndDate = date;
        }
    }

    private void ToggleCurrentJob(int index, bool isCurrent)
    {
        WorkEntries[index].IsCurrent = isCurrent;
        if (isCurrent) WorkEntries[index].EndDate = null;
    }

    // Reference helpers
    private void AddReference() { if (References.Count < 3) References.Add(new ReferenceModel()); }
    private void RemoveReference(int index) => References.RemoveAt(index);

    private void UpdateReference(int index, string field, string? value)
    {
        var r = References[index];
        switch (field)
        {
            case nameof(ReferenceModel.Name): r.Name = value ?? string.Empty; break;
            case nameof(ReferenceModel.Relationship): r.Relationship = value ?? string.Empty; break;
            case nameof(ReferenceModel.Email): r.Email = value ?? string.Empty; break;
            case nameof(ReferenceModel.Phone): r.Phone = value ?? string.Empty; break;
        }
    }

    // Mutable models for form binding
    private class WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime? StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private class ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }
}

