+@page "/apply"
+@rendermode InteractiveServer
+@using sv_56e4b75ff8b646548b4b84659ecf202a.Models
+@inject IApplicationService ApplicationService
+
+<PageTitle>Job Application</PageTitle>
+
+<h1>Job Application</h1>
+
+<!-- Step Indicator Bar -->
+<div class="step-indicator">
+    @for (int i = 0; i < StepNames.Length; i++)
+    {
+        var stepIndex = i;
+        var stepClass = GetStepClass(stepIndex);
+        <div class="step @stepClass" @onclick="() => GoToStep(stepIndex)">
+            <div class="step-circle">
+                @if (stepIndex < CurrentStep)
+                {
+                    <span>&#10003;</span>
+                }
+                else
+                {
+                    <span>@(stepIndex + 1)</span>
+                }
+            </div>
+            <div class="step-label">@StepNames[stepIndex]</div>
+        </div>
+        @if (i < StepNames.Length - 1)
+        {
+            <div class="step-connector @(stepIndex < CurrentStep ? "completed" : "")"></div>
+        }
+    }
+</div>
+
+@if (!string.IsNullOrEmpty(ErrorMessage))
+{
+    <div class="alert alert-danger mt-3">@ErrorMessage</div>
+}
+
+<!-- Step 1: Personal Info -->
+@if (CurrentStep == 0)
+{
+    <div class="form-section">
+        <h2>Personal Information</h2>
+        <div class="mb-3">
+            <label class="form-label">Full Name *</label>
+            <input type="text" class="form-control" @bind="FullName" />
+        </div>
+        <div class="mb-3">
+            <label class="form-label">Email *</label>
+            <input type="email" class="form-control" @bind="Email" />
+        </div>
+        <div class="mb-3">
+            <label class="form-label">Phone *</label>
+            <input type="tel" class="form-control" @bind="Phone" />
+        </div>
+        <div class="mb-3">
+            <label class="form-label">Address *</label>
+            <input type="text" class="form-control" @bind="Address" />
+        </div>
+        <div class="d-flex justify-content-end">
+            <button class="btn btn-primary" @onclick="NextFromPersonalInfo" disabled="@IsLoading">
+                @if (IsLoading) { <span>Validating...</span> } else { <span>Next</span> }
+            </button>
+        </div>
+    </div>
+}
+
+<!-- Step 2: Work History -->
+@if (CurrentStep == 1)
+{
+    <div class="form-section">
+        <h2>Work History</h2>
+        @for (int i = 0; i < WorkEntries.Count; i++)
+        {
+            var index = i;
+            <div class="card mb-3 p-3">
+                <h5>Position @(index + 1)</h5>
+                <div class="mb-3">
+                    <label class="form-label">Company *</label>
+                    <input type="text" class="form-control" value="@WorkEntries[index].Company"
+                           @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Company), e.Value?.ToString())" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Job Title *</label>
+                    <input type="text" class="form-control" value="@WorkEntries[index].Title"
+                           @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Title), e.Value?.ToString())" />
+                </div>
+                <div class="row mb-3">
+                    <div class="col-md-6">
+                        <label class="form-label">Start Date *</label>
+                        <input type="date" class="form-control" value="@WorkEntries[index].StartDate?.ToString("yyyy-MM-dd")"
+                               @onchange="(e) => UpdateWorkEntryDate(index, true, e.Value?.ToString())" />
+                    </div>
+                    <div class="col-md-6">
+                        <label class="form-label">End Date</label>
+                        <input type="date" class="form-control" value="@WorkEntries[index].EndDate?.ToString("yyyy-MM-dd")"
+                               disabled="@WorkEntries[index].IsCurrent"
+                               @onchange="(e) => UpdateWorkEntryDate(index, false, e.Value?.ToString())" />
+                        <div class="form-check mt-1">
+                            <input class="form-check-input" type="checkbox" checked="@WorkEntries[index].IsCurrent"
+                                   @onchange="(e) => ToggleCurrentJob(index, (bool)(e.Value ?? false))" />
+                            <label class="form-check-label">Currently working here</label>
+                        </div>
+                    </div>
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Description</label>
+                    <textarea class="form-control" rows="3" value="@WorkEntries[index].Description"
+                              @onchange="(e) => UpdateWorkEntry(index, nameof(WorkEntryModel.Description), e.Value?.ToString())"></textarea>
+                </div>
+                @if (WorkEntries.Count > 1)
+                {
+                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(index)">Remove</button>
+                }
+            </div>
+        }
+        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">+ Add Another Position</button>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromWorkHistory">Next</button>
+        </div>
+    </div>
+}
+
+<!-- Step 3: References -->
+@if (CurrentStep == 2)
+{
+    <div class="form-section">
+        <h2>References</h2>
+        @for (int i = 0; i < References.Count; i++)
+        {
+            var index = i;
+            <div class="card mb-3 p-3">
+                <h5>Reference @(index + 1)</h5>
+                <div class="mb-3">
+                    <label class="form-label">Name *</label>
+                    <input type="text" class="form-control" value="@References[index].Name"
+                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Name), e.Value?.ToString())" />
+                </div>
+                <div class="mb-3">
+                    <label class="form-label">Relationship *</label>
+                    <input type="text" class="form-control" value="@References[index].Relationship"
+                           @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Relationship), e.Value?.ToString())" />
+                </div>
+                <div class="row mb-3">
+                    <div class="col-md-6">
+                        <label class="form-label">Email *</label>
+                        <input type="email" class="form-control" value="@References[index].Email"
+                               @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Email), e.Value?.ToString())" />
+                    </div>
+                    <div class="col-md-6">
+                        <label class="form-label">Phone *</label>
+                        <input type="tel" class="form-control" value="@References[index].Phone"
+                               @onchange="(e) => UpdateReference(index, nameof(ReferenceModel.Phone), e.Value?.ToString())" />
+                    </div>
+                </div>
+                @if (References.Count > 2)
+                {
+                    <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(index)">Remove</button>
+                }
+            </div>
+        }
+        @if (References.Count < 3)
+        {
+            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">+ Add Reference</button>
+        }
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextFromReferences">Next</button>
+        </div>
+    </div>
+}
+
+<!-- Step 4: Cover Letter -->
+@if (CurrentStep == 3)
+{
+    <div class="form-section">
+        <h2>Cover Letter</h2>
+        <div class="mb-3">
+            <textarea class="form-control" rows="12" maxlength="2000" @bind="CoverLetter" @bind:event="oninput"></textarea>
+            <div class="text-muted mt-1">@CoverLetter.Length / 2000 characters</div>
+        </div>
+        <div class="d-flex justify-content-between">
+            <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+            <button class="btn btn-primary" @onclick="NextStep">Next</button>
+        </div>
+    </div>
+}
+
+<!-- Step 5: Review & Submit -->
+@if (CurrentStep == 4)
+{
+    @if (IsSubmitted)
+    {
+        <div class="form-section text-center">
+            <h2 class="text-success">Application Submitted!</h2>
+            <p class="fs-5">Your application has been successfully submitted.</p>
+            <p class="fs-4"><strong>Application ID: @SubmittedApplicationId</strong></p>
+        </div>
+    }
+    else
+    {
+        <div class="form-section">
+            <h2>Review & Submit</h2>
+
+            <!-- Personal Info Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Personal Information</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(0)">Edit</a>
+                </div>
+                <p><strong>Name:</strong> @FullName</p>
+                <p><strong>Email:</strong> @Email</p>
+                <p><strong>Phone:</strong> @Phone</p>
+                <p><strong>Address:</strong> @Address</p>
+            </div>
+
+            <!-- Work History Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Work History</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(1)">Edit</a>
+                </div>
+                @foreach (var entry in WorkEntries)
+                {
+                    <div class="mb-2 ps-2 border-start">
+                        <p class="mb-1"><strong>@entry.Title</strong> at @entry.Company</p>
+                        <p class="mb-1 text-muted">
+                            @entry.StartDate?.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
+                        </p>
+                        @if (!string.IsNullOrWhiteSpace(entry.Description))
+                        {
+                            <p class="mb-1">@entry.Description</p>
+                        }
+                    </div>
+                }
+            </div>
+
+            <!-- References Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>References</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(2)">Edit</a>
+                </div>
+                @foreach (var reference in References)
+                {
+                    <div class="mb-2 ps-2 border-start">
+                        <p class="mb-1"><strong>@reference.Name</strong> (@reference.Relationship)</p>
+                        <p class="mb-1 text-muted">@reference.Email | @reference.Phone</p>
+                    </div>
+                }
+            </div>
+
+            <!-- Cover Letter Review -->
+            <div class="card mb-3 p-3">
+                <div class="d-flex justify-content-between align-items-center">
+                    <h5>Cover Letter</h5>
+                    <a href="javascript:void(0)" @onclick="() => GoToStep(3)">Edit</a>
+                </div>
+                <p style="white-space: pre-wrap;">@CoverLetter</p>
+            </div>
+
+            <div class="d-flex justify-content-between">
+                <button class="btn btn-secondary" @onclick="PreviousStep">Back</button>
+                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@IsLoading">
+                    @if (IsLoading) { <span>Submitting...</span> } else { <span>Submit Application</span> }
+                </button>
+            </div>
+        </div>
+    }
+}
+
+@code {
+    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
+
+    private int CurrentStep { get; set; }
+    private int HighestCompletedStep { get; set; } = -1;
+    private bool IsLoading { get; set; }
+    private bool IsSubmitted { get; set; }
+    private int SubmittedApplicationId { get; set; }
+    private string ErrorMessage { get; set; } = string.Empty;
+
+    // Step 1 fields
+    private string FullName { get; set; } = string.Empty;
+    private string Email { get; set; } = string.Empty;
+    private string Phone { get; set; } = string.Empty;
+    private string Address { get; set; } = string.Empty;
+
+    // Step 2 fields
+    private List<WorkEntryModel> WorkEntries { get; set; } = new() { new WorkEntryModel() };
+
+    // Step 3 fields
+    private List<ReferenceModel> References { get; set; } = new() { new ReferenceModel(), new ReferenceModel() };
+
+    // Step 4 fields
+    private string CoverLetter { get; set; } = string.Empty;
+
+    private string GetStepClass(int stepIndex)
+    {
+        if (stepIndex == CurrentStep) return "active";
+        if (stepIndex <= HighestCompletedStep) return "completed";
+        return "future";
+    }
+
+    private void GoToStep(int step)
+    {
+        if (step <= HighestCompletedStep || step == CurrentStep)
+        {
+            ErrorMessage = string.Empty;
+            CurrentStep = step;
+        }
+    }
+
+    private void NextStep()
+    {
+        ErrorMessage = string.Empty;
+        if (CurrentStep > HighestCompletedStep)
+            HighestCompletedStep = CurrentStep;
+        CurrentStep++;
+    }
+
+    private void PreviousStep()
+    {
+        ErrorMessage = string.Empty;
+        CurrentStep--;
+    }
+
+    private async Task NextFromPersonalInfo()
+    {
+        ErrorMessage = string.Empty;
+
+        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email) ||
+            string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
+        {
+            ErrorMessage = "Please fill in all required fields.";
+            return;
+        }
+
+        IsLoading = true;
+        try
+        {
+            var isValidEmail = await ApplicationService.ValidateEmailAsync(Email);
+            if (!isValidEmail)
+            {
+                ErrorMessage = "The email address is not valid. Please enter a valid email.";
+                return;
+            }
+            NextStep();
+        }
+        finally
+        {
+            IsLoading = false;
+        }
+    }
+
+    private void NextFromWorkHistory()
+    {
+        ErrorMessage = string.Empty;
+        foreach (var entry in WorkEntries)
+        {
+            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title) || entry.StartDate == null)
+            {
+                ErrorMessage = "Please fill in company, job title, and start date for all positions.";
+                return;
+            }
+        }
+        NextStep();
+    }
+
+    private void NextFromReferences()
+    {
+        ErrorMessage = string.Empty;
+        foreach (var reference in References)
+        {
+            if (string.IsNullOrWhiteSpace(reference.Name) || string.IsNullOrWhiteSpace(reference.Relationship) ||
+                string.IsNullOrWhiteSpace(reference.Email) || string.IsNullOrWhiteSpace(reference.Phone))
+            {
+                ErrorMessage = "Please fill in all required fields for each reference.";
+                return;
+            }
+        }
+        NextStep();
+    }
+
+    private async Task SubmitApplication()
+    {
+        IsLoading = true;
+        ErrorMessage = string.Empty;
+        try
+        {
+            var personal = new PersonalInfo(FullName, Email, Phone, Address);
+            var workHistory = new WorkHistory(WorkEntries.Select(e =>
+                new WorkEntry(e.Company, e.Title, e.StartDate ?? DateTime.MinValue, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
+            var references = References.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
+            var application = new JobApplication(personal, workHistory, references, CoverLetter);
+
+            SubmittedApplicationId = await ApplicationService.SubmitApplicationAsync(application);
+            IsSubmitted = true;
+        }
+        catch (Exception ex)
+        {
+            ErrorMessage = $"Submission failed: {ex.Message}";
+        }
+        finally
+        {
+            IsLoading = false;
+        }
+    }
+
+    // Work entry helpers
+    private void AddWorkEntry() => WorkEntries.Add(new WorkEntryModel());
+    private void RemoveWorkEntry(int index) => WorkEntries.RemoveAt(index);
+
+    private void UpdateWorkEntry(int index, string field, string? value)
+    {
+        var entry = WorkEntries[index];
+        switch (field)
+        {
+            case nameof(WorkEntryModel.Company): entry.Company = value ?? string.Empty; break;
+            case nameof(WorkEntryModel.Title): entry.Title = value ?? string.Empty; break;
+            case nameof(WorkEntryModel.Description): entry.Description = value ?? string.Empty; break;
+        }
+    }
+
+    private void UpdateWorkEntryDate(int index, bool isStart, string? value)
+    {
+        if (DateTime.TryParse(value, out var date))
+        {
+            if (isStart) WorkEntries[index].StartDate = date;
+            else WorkEntries[index].EndDate = date;
+        }
+    }
+
+    private void ToggleCurrentJob(int index, bool isCurrent)
+    {
+        WorkEntries[index].IsCurrent = isCurrent;
+        if (isCurrent) WorkEntries[index].EndDate = null;
+    }
+
+    // Reference helpers
+    private void AddReference() { if (References.Count < 3) References.Add(new ReferenceModel()); }
+    private void RemoveReference(int index) => References.RemoveAt(index);
+
+    private void UpdateReference(int index, string field, string? value)
+    {
+        var r = References[index];
+        switch (field)
+        {
+            case nameof(ReferenceModel.Name): r.Name = value ?? string.Empty; break;
+            case nameof(ReferenceModel.Relationship): r.Relationship = value ?? string.Empty; break;
+            case nameof(ReferenceModel.Email): r.Email = value ?? string.Empty; break;
+            case nameof(ReferenceModel.Phone): r.Phone = value ?? string.Empty; break;
+        }
+    }
+
+    // Mutable models for form binding
+    private class WorkEntryModel
+    {
+        public string Company { get; set; } = string.Empty;
+        public string Title { get; set; } = string.Empty;
+        public DateTime? StartDate { get; set; }
+        public DateTime? EndDate { get; set; }
+        public bool IsCurrent { get; set; }
+        public string Description { get; set; } = string.Empty;
+    }
+
+    private class ReferenceModel
+    {
+        public string Name { get; set; } = string.Empty;
+        public string Relationship { get; set; } = string.Empty;
+        public string Email { get; set; } = string.Empty;
+        public string Phone { get; set; } = string.Empty;
+    }
+}
+

